/** bool8 ScrCmd_braillemessage(struct ScriptContext *ctx) */
export function ScrCmd_braillemessage(ctx: any): any {
  let ptr: any = ScriptReadWord(ctx);
      let winTemplate: any = null;
      let i: any = null;
      let width, height;
      let xWindow, yWindow, xText, yText;
      let temp: any = null;

       
       
       
      StringExpandPlaceholders(gStringVar4, ptr + 6);

      width = GetStringWidth(FONT_BRAILLE, gStringVar4, -1) / 8;

      if (width > 28)
          width = 28;

      for (i = 0, height = 4; gStringVar4[i] != (0xFF);)
      {
          if (gStringVar4[i++] == (0xFE))
              height += 3;
      }

      if (height > 18)
          height = 18;

      temp = width + 2;
      xWindow = (30 - temp) / 2;

      temp = height + 2;
      yText = (20 - temp) / 2;

      xText = xWindow;
      xWindow += 1;

      yWindow = yText;
      yText += 2;

      xText = (xWindow - xText - 1) * 8 + 3;
      yText = (yText - yWindow - 1) * 8;

      winTemplate = CreateWindowTemplate(0, xWindow, yWindow + 1, width, height, 0xF, 0x1);
      sBrailleWindowId = AddWindow(winTemplate);
      LoadUserWindowBorderGfx(sBrailleWindowId, 0x214, BG_PLTT_ID(14));
      DrawStdWindowFrame(sBrailleWindowId, FALSE);
      PutWindowTilemap(sBrailleWindowId);
      FillWindowPixelBuffer(sBrailleWindowId, PIXEL_FILL(1));
      AddTextPrinterParameterized(sBrailleWindowId, FONT_BRAILLE, gStringVar4, xText, yText, (0xFF), NULL);
      CopyWindowToVram(sBrailleWindowId, COPYWIN_FULL);
      return FALSE;
}

